package com.trombokendu.chronos.analytics;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.random.*;public final class MonteCarloEngine{private final ForkJoinPool pool;public MonteCarloEngine(int threads){pool=new ForkJoinPool(threads);}public ForecastResult simulate(ForecastRequest q){int chunks=Math.min(pool.getParallelism(),q.paths());SplittableRandom master=new SplittableRandom(q.seed());List<CompletableFuture<double[][]>> jobs=new ArrayList<>();for(int c=0;c<chunks;c++){int count=q.paths()/chunks+(c<q.paths()%chunks?1:0);SplittableRandom rng=master.split();jobs.add(CompletableFuture.supplyAsync(()->runChunk(q,count,rng),pool));}CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new)).join();List<double[]> paths=new ArrayList<>();for(var j:jobs)for(double[] x:j.join())paths.add(x);double[][] bands=new double[3][q.horizon()+1];double breaches=0;double[] ends=new double[paths.size()];List<Integer> zeros=new ArrayList<>();for(int i=0;i<paths.size();i++){double[] x=paths.get(i);ends[i]=x[x.length-1];int z=-1;for(int d=0;d<x.length;d++)if(x[d]<0){z=d;break;}if(z>=0){breaches++;zeros.add(z);}}for(int d=0;d<=q.horizon();d++){double[] col=new double[paths.size()];for(int i=0;i<paths.size();i++)col[i]=paths.get(i)[d];Arrays.sort(col);bands[0][d]=quantile(col,.1);bands[1][d]=quantile(col,.5);bands[2][d]=quantile(col,.9);}Arrays.sort(ends);LocalDate[] run={q.start().plusDays((long)quantile(zeros.stream().mapToDouble(Integer::doubleValue).sorted().toArray(),.1)),q.start().plusDays((long)quantile(zeros.stream().mapToDouble(Integer::doubleValue).sorted().toArray(),.5)),q.start().plusDays((long)quantile(zeros.stream().mapToDouble(Integer::doubleValue).sorted().toArray(),.9))};return new ForecastResult(breaches/paths.size(),0,run,new LocalDate[]{run[0]},new LocalDate[]{run[2]},bands,Arrays.stream(ends).average().orElse(0));}private double[][] runChunk(ForecastRequest q,int n,SplittableRandom rng){double[][] out=new double[n][q.horizon()+1];for(int i=0;i<n;i++){double b=q.currentBalance();out[i][0]=b;for(int d=1;d<=q.horizon();d++){LocalDate date=q.start().plusDays(d-1);double mu=q.dailyMeans().getOrDefault(date.getDayOfWeek(),0.0);double noise=(rng.nextDouble()+rng.nextDouble()+rng.nextDouble()-1.5)*mu*.5;b-=Math.max(0,mu+noise);out[i][d]=b;}}return out;}private static double quantile(double[]x,double q){if(x.length==0)return 0;return x[Math.min(x.length-1,(int)Math.floor(q*(x.length-1)))];}public void close(){pool.shutdown();}}
